/**
 * NBA Sport Adapter — second sport in the PropWire sport layer.
 *
 * v1 STATUS: RESEARCH FIXTURES ONLY. The NBA slate/games/odds/availability
 * feeds shipped with this adapter are synthetic fixtures (every row, quote
 * and injury item carries _fixture: true) used to validate the multi-sport
 * UI, breaker plumbing, ledger provenance, Top-Play ranking and the full
 * availability/surge machinery before any live data source is wired. Two
 * fixture nights are registered: the Oct 22 opener (2 games) and the Oct 23
 * full night (10 games, generated by scripts/build_nba_fixtures.py). Per the
 * Phase 0.5 data-source gate, the documented clean source (balldontlie NBA
 * API) gates box scores behind a paid tier; when a key is supplied,
 * scripts/fetch_nba.py writes real feeds with _fixture: false into the same
 * schema and the fixtures are retired.
 *
 * Breaker values are UNCALIBRATED tuning parameters (calibrated: false in
 * both this fallback and circuit_breaker_config.json sports.nba) and the UI
 * must surface the research-only badge whenever the active sport is not
 * calibrated. Never copy NFL yardage/recemption thresholds here.
 *
 * Timezone semantics (user-approved default): slates are keyed by US Eastern
 * calendar date; feed timestamps are ISO-8601 UTC; display renders local time
 * with an explicit TZ label. etDateKey() is the single source of truth for
 * the date-key mapping and is mirrored in scripts/fetch_nba.py.
 */
(() => {
  'use strict';

  let ctx = {};
  const num = (...args) => ctx.num(...args);
  const pct = (...args) => ctx.pct(...args);
  const esc = (...args) => ctx.esc(...args);

  /**
   * Calendar date of an ISO-8601 UTC timestamp in US Eastern time.
   * Handles DST boundaries (EDT UTC-4 / EST UTC-5) via the IANA tz database.
   */
  function etDateKey(iso) {
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return null;
    return new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).format(date);
  }

  /** Normal-approximation P(over line) for a mu/sd pair (fixture model). */
  function normalOver(mu, sd, line) {
    if (!(sd > 0)) return num(line) < mu ? 1 : num(line) > mu ? 0 : 0.5;
    const z = (line + 0.5 - mu) / sd; // continuity correction for discrete-ish lines
    return 1 / (1 + Math.exp(-1.702 * z)); // logistic approx of Phi(z), max err ~0.009
  }

  const NBA_ADAPTER = {
    id: 'nba',
    label: 'NBA',
    periodNoun: 'Slate',

    /** Historical fixture rows remain flagged individually; market-only slates are real but unverified. */
    fixturesOnly: false,
    fixtureNotice: 'Research fixtures — synthetic model data for terminal validation. Not sportsbook quotes. Not for wagering decisions.',
    pageTitle: 'PropStein · NBA Player Props Research',

    /** Allow viewer/app.js to lend its helper functions to hook implementations. */
    bindContext(helpers) {
      ctx = helpers || {};
    },

    // ── Distribution model constants ────────────────────────────────────────
    // NBA v1 uses normal-approximation ranges per market (mu/sd on each row);
    // the NFL NegBin/Gamma constants do not apply and are intentionally absent.
    model: null,

    // ── Slate registry (slates keyed by US Eastern calendar date) ───────────
    // Registration order IS the selector order and the defaultSlateKey search
    // order — the Oct 22 opener stays first so the boot default is unchanged.
    slates: {
      '2026-10-22': {
        season: 2026,
        date: '2026-10-22',
        shortLabel: 'Oct 22 Fixture',
        state: 'Fixture slate · Oct 22, 2026',
        slate: 'nba_slate_2026-10-22.json',
        games: 'nba_games_2026-10-22.json',
        picks: null,
        injuries: 'nba_injuries_2026-10-22.json',
        odds: 'nba_odds_2026-10-22.json',
        snapshots: null,
        historical: false,
        timezone: 'America/New_York'
      },
      '2026-10-23': {
        season: 2026,
        date: '2026-10-23',
        shortLabel: 'Oct 23 Fixture',
        state: 'Fixture slate · Oct 23, 2026',
        slate: 'nba_slate_2026-10-23.json',
        games: 'nba_games_2026-10-23.json',
        picks: null,
        injuries: 'nba_injuries_2026-10-23.json',
        odds: 'nba_odds_2026-10-23.json',
        snapshots: null,
        historical: false,
        timezone: 'America/New_York'
      },
      '2026-10-29': {
        season: 2026,
        date: '2026-10-29',
        shortLabel: 'Oct 29 Slate',
        state: 'Upcoming slate · Oct 29, 2026',
        slate: 'nba_slate_2026-10-29.json',
        games: 'nba_games_2026-10-29.json',
        picks: null,
        injuries: 'nba_injuries_2026-10-29.json',
        odds: 'nba_odds_2026-10-29.json',
        snapshots: null,
        historical: false,
        timezone: 'America/New_York'
      }
    },

    /** Default slate = in live production (Date > Oct 22), default to tomorrow's slate (Oct 29). In frozen tests (Date <= Oct 22), default to Oct 22. */
    defaultSlateKey() {
      if (Date.now() > 1792670400000 && this.slates['2026-10-29']) {
        return '2026-10-29';
      }
      const key = Object.keys(this.slates).find((k) => !this.slates[k].historical);
      return key || Object.keys(this.slates)[0] || null;
    },

    // ── Markets (5 NBA v1 markets; all normal-approximation, uncalibrated) ──
    markets: {
      points: {
        id: 'points',
        chipLabel: 'PTS',
        unit: 'pts',
        bulletUnit: 'pts',
        naturalInsightUnit: 'pts',
        settledUnit: 'pts',
        breakerUnit: 'pts',
        isYards: false,
        strongCeiling: 30.0,
        breaker: { driftHurdle: 3.0, beneficiaryMax: 5.0 },
        fair: (row) => num(row.fair_line_pts),
        projection: (row) => num(row.proj_pts),
        actual: (row) => num(row.pts),
        settledActual: (row) => num(row.pts),
        settledLine: (row) => num(row.fair_line_pts),
        fairProbText: () => 'P(over fair) 50.0%',
        mu: (row) => num(row.mu_pts || row.fair_line_pts || row.proj_pts),
        sd: (row) => num(row.sd_pts) || Math.max(1, num(row.mu_pts || row.fair_line_pts || row.proj_pts) * 0.35),
        dist: (row) => {
          const m = NBA_ADAPTER.markets.points;
          const mu = m.mu(row);
          const sd = m.sd(row);
          return { low: Math.max(0, Math.round(mu - 0.9 * sd)), high: Math.round(mu + 0.9 * sd), fair: num(row.fair_line_pts), proj: num(row.proj_pts), isRec: false };
        },
        prediction: (row) => {
          const { low, high } = NBA_ADAPTER.markets.points.dist(row);
          return `80% Range: ${low} – ${high} pts`;
        }
      },
      rebounds: {
        id: 'rebounds',
        chipLabel: 'REB',
        unit: 'reb',
        bulletUnit: 'reb',
        naturalInsightUnit: 'reb',
        settledUnit: 'reb',
        breakerUnit: 'reb',
        isYards: false,
        strongCeiling: 13.0,
        breaker: { driftHurdle: 2.0, beneficiaryMax: 3.5 },
        fair: (row) => num(row.fair_line_reb),
        projection: (row) => num(row.proj_reb),
        actual: (row) => num(row.rebounds),
        settledActual: (row) => num(row.rebounds),
        settledLine: (row) => num(row.fair_line_reb),
        fairProbText: () => 'P(over fair) 50.0%',
        mu: (row) => num(row.mu_reb || row.fair_line_reb || row.proj_reb),
        sd: (row) => num(row.sd_reb) || Math.max(1, num(row.mu_reb || row.fair_line_reb || row.proj_reb) * 0.35),
        dist: (row) => {
          const m = NBA_ADAPTER.markets.rebounds;
          const mu = m.mu(row);
          const sd = m.sd(row);
          return { low: Math.max(0, Math.round(mu - 0.9 * sd)), high: Math.round(mu + 0.9 * sd), fair: num(row.fair_line_reb), proj: num(row.proj_reb), isRec: true };
        },
        prediction: (row) => {
          const { low, high } = NBA_ADAPTER.markets.rebounds.dist(row);
          return `80% Range: ${low} – ${high} reb`;
        }
      },
      assists: {
        id: 'assists',
        chipLabel: 'AST',
        unit: 'ast',
        bulletUnit: 'ast',
        naturalInsightUnit: 'ast',
        settledUnit: 'ast',
        breakerUnit: 'ast',
        isYards: false,
        strongCeiling: 9.0,
        breaker: { driftHurdle: 2.0, beneficiaryMax: 3.5 },
        fair: (row) => num(row.fair_line_ast),
        projection: (row) => num(row.proj_ast),
        actual: (row) => num(row.assists),
        settledActual: (row) => num(row.assists),
        settledLine: (row) => num(row.fair_line_ast),
        fairProbText: () => 'P(over fair) 50.0%',
        mu: (row) => num(row.mu_ast || row.fair_line_ast || row.proj_ast),
        sd: (row) => num(row.sd_ast) || Math.max(1, num(row.mu_ast || row.fair_line_ast || row.proj_ast) * 0.35),
        dist: (row) => {
          const m = NBA_ADAPTER.markets.assists;
          const mu = m.mu(row);
          const sd = m.sd(row);
          return { low: Math.max(0, Math.round(mu - 0.9 * sd)), high: Math.round(mu + 0.9 * sd), fair: num(row.fair_line_ast), proj: num(row.proj_ast), isRec: true };
        },
        prediction: (row) => {
          const { low, high } = NBA_ADAPTER.markets.assists.dist(row);
          return `80% Range: ${low} – ${high} ast`;
        }
      },
      threes: {
        id: 'threes',
        chipLabel: '3PM',
        unit: '3pm',
        bulletUnit: '3pm',
        naturalInsightUnit: '3pm',
        settledUnit: '3pm',
        breakerUnit: '3pm',
        isYards: false,
        strongCeiling: 4.0,
        breaker: { driftHurdle: 1.0, beneficiaryMax: 1.5 },
        fair: (row) => num(row.fair_line_fg3m),
        projection: (row) => num(row.proj_fg3m),
        actual: (row) => num(row.fg3m),
        settledActual: (row) => num(row.fg3m),
        settledLine: (row) => num(row.fair_line_fg3m),
        fairProbText: () => 'P(over fair) 50.0%',
        mu: (row) => num(row.mu_fg3m || row.fair_line_fg3m || row.proj_fg3m),
        sd: (row) => num(row.sd_fg3m) || Math.max(0.5, num(row.mu_fg3m || row.fair_line_fg3m || row.proj_fg3m) * 0.35),
        dist: (row) => {
          const m = NBA_ADAPTER.markets.threes;
          const mu = m.mu(row);
          const sd = m.sd(row);
          return { low: Math.max(0, Math.round(mu - 0.9 * sd)), high: Math.round(mu + 0.9 * sd), fair: num(row.fair_line_fg3m), proj: num(row.proj_fg3m), isRec: true };
        },
        prediction: (row) => {
          const { low, high } = NBA_ADAPTER.markets.threes.dist(row);
          return `80% Range: ${low} – ${high} 3pm`;
        }
      },
      pra: {
        id: 'pra',
        chipLabel: 'PRA',
        unit: 'pra',
        bulletUnit: 'pra',
        naturalInsightUnit: 'pra',
        settledUnit: 'pra',
        breakerUnit: 'pra',
        isYards: false,
        strongCeiling: 45.0,
        breaker: { driftHurdle: 5.0, beneficiaryMax: 8.0 },
        fair: (row) => num(row.fair_line_pra),
        projection: (row) => num(row.proj_pra),
        actual: (row) => num(num(row.pts) + num(row.rebounds) + num(row.assists)),
        settledActual: (row) => num(num(row.pts) + num(row.rebounds) + num(row.assists)),
        settledLine: (row) => num(row.fair_line_pra),
        fairProbText: () => 'P(over fair) 50.0%',
        mu: (row) => num(row.mu_pra || row.fair_line_pra || row.proj_pra),
        sd: (row) => num(row.sd_pra) || Math.max(2, num(row.mu_pra || row.fair_line_pra || row.proj_pra) * 0.28),
        dist: (row) => {
          const m = NBA_ADAPTER.markets.pra;
          const mu = m.mu(row);
          const sd = m.sd(row);
          return { low: Math.max(0, Math.round(mu - 0.9 * sd)), high: Math.round(mu + 0.9 * sd), fair: num(row.fair_line_pra), proj: num(row.proj_pra), isRec: false };
        },
        prediction: (row) => {
          const { low, high } = NBA_ADAPTER.markets.pra.dist(row);
          return `80% Range: ${low} – ${high} pra`;
        }
      }
    },

    defaultMarket: 'points',
    marketOrder: ['points', 'rebounds', 'assists', 'threes', 'pra'],

    // ── Positions / intents ─────────────────────────────────────────────────
    positions: ['PG', 'SG', 'SF', 'PF', 'C'],

    /** Filter-sheet intent labels — NBA renames "Deep" to "Primary option". */
    intents: [
      { id: 'surge', label: 'Surge' },
      { id: 'volume', label: 'Volume' },
      { id: 'deep', label: 'Primary' }
    ],

    intentFilters: {
      surge: (row, beneficiary) => Boolean(beneficiary),
      volume: (row) => num(row.usage_rate) >= 0.28 || num(row.minutes) >= 34,
      deep: (row) => num(row.usage_rate) >= 0.30 && num(row.minutes) >= 33
    },

    /** Top Plays mode source: EV-ranked from quote evaluations (no picks file). */
    topPlays: { source: 'ev_ranked' },

    /**
     * Top Plays data gate: rows missing the projection/fair inputs for the
     * active market are hidden from the ranked view (spec: incomplete
     * projection inputs → excluded, never rendered with partial math).
     */
    hasCompleteInputs(row, market) {
      const mdef = this.markets[market] || this.markets[this.defaultMarket];
      return Number.isFinite(Number(mdef.fair(row))) && Number.isFinite(Number(mdef.projection(row)))
        && num(mdef.fair(row)) > 0 && num(mdef.projection(row)) > 0;
    },

    /** Default (non-EV) sort: active market projection, desc. */
    sortDefault(row, market) {
      const mdef = this.markets[market] || this.markets[this.defaultMarket];
      return num(mdef.projection(row));
    },

    // ── Role / driver tags (usage & minutes; no target-share semantics) ─────
    roleLabel(row) {
      const usage = num(row.usage_rate);
      const minutes = num(row.minutes);
      if (usage >= 0.30 || minutes >= 36) return `Primary ${row.position}`;
      if (usage >= 0.22 || minutes >= 28) return `Rotation ${row.position}`;
      return `Bench ${row.position}`;
    },

    driverTag(row, beneficiary) {
      const { SVG_ICONS } = ctx;
      if (beneficiary) {
        return `<span class="driver-badge surge" title="Role surge catalyst: ${esc(beneficiary.catalyst_injury || 'Vacancy')}">${SVG_ICONS.surge} Surge (+${num(beneficiary.added_minutes).toFixed(0)} min)</span>`;
      }
      const usage = num(row.usage_rate);
      const minutes = num(row.minutes);
      if (usage >= 0.32) {
        return `<span class="driver-badge alpha" title="Usage rate: ${pct(usage, 0)}">${SVG_ICONS.alpha} Usage (${pct(usage, 0)})</span>`;
      }
      if (minutes >= 36) {
        return `<span class="driver-badge volume" title="Minutes: ${minutes.toFixed(0)} min/gm">${SVG_ICONS.volume} ${minutes.toFixed(0)} MIN</span>`;
      }
      if (usage >= 0.24) {
        return `<span class="driver-badge starter" title="Secondary usage: ${pct(usage, 0)}">${SVG_ICONS.starter} Secondary (${pct(usage, 0)})</span>`;
      }
      return `<span class="driver-badge depth" title="Bench rotation role">${SVG_ICONS.depth} Bench</span>`;
    },

    // ── Detail modal hooks (NFL's verbatim hooks live in nfl.js) ────────────
    detail: {
      scenarioCapable: false,
      marketLabel: (market) => ({
        points: 'Points',
        rebounds: 'Rebounds',
        assists: 'Assists',
        threes: 'Threes made',
        pra: 'Points + Rebounds + Assists'
      })[market] || market,
      modelSpec: () => 'MODEL SPEC: NORMAL APPROX (UNCALIBRATED)',
      distributionDesc: () => 'Continuous Normal Approximation',
      sampleNote: (row) => `Fixture baseline (uncalibrated) · ${row.season || '2026-27'}`,
      scopeNote: () => 'NBA fixture fair lines are normal-approximation medians with P(over) = 50.0%. Uncalibrated research parameters — treat all outputs as directional only.',
      environment: () => ({ tag: 'INDOOR ARENA', desc: 'Fixed indoor venue (fixture slate — weather not modeled)' })
    },

    // ── UI labels ───────────────────────────────────────────────────────────
    labels: {
      byeImpact: () => 'No availability alerts on fixture slate',
      ticker: {
        games: (n) => `${n} Games`,
        teams: (n) => `${n} Teams`,
        records: (n) => `${n} Modeled player records`,
        ingestedTail: (ingested) => `${ingested} fixture rows (no book verification)`
      },
      injuredQuantImpact: {
        vacated: (item) => `Vacates ${item.vacated_minutes} min/g (${item.vacated_usage ? `${pct(item.vacated_usage, 0)} usage` : 'high usage'})`
      }
    },

    // ── Team logo map (30 NBA franchises; ESPN NBA CDN) ─────────────────────
    logo: {
      espnCdnBase: 'https://a.espncdn.com/i/teamlogos/nba/500/',
      map: {
        ATL: { slug: 'atl', bg: 'rgba(199,30,49,0.18)', border: 'rgba(199,30,49,0.45)' },
        BOS: { slug: 'bos', bg: 'rgba(0,122,51,0.20)', border: 'rgba(186,178,138,0.50)' },
        BKN: { slug: 'bkn', bg: 'rgba(0,0,0,0.35)', border: 'rgba(255,255,255,0.35)' },
        CHA: { slug: 'cha', bg: 'rgba(0,120,140,0.20)', border: 'rgba(109,68,143,0.45)' },
        CHI: { slug: 'chi', bg: 'rgba(206,17,38,0.18)', border: 'rgba(0,0,0,0.45)' },
        CLE: { slug: 'cle', bg: 'rgba(134,0,56,0.20)', border: 'rgba(219,108,15,0.45)' },
        DAL: { slug: 'dal', bg: 'rgba(0,83,188,0.20)', border: 'rgba(178,95,40,0.45)' },
        DEN: { slug: 'den', bg: 'rgba(27,68,240,0.18)', border: 'rgba(255,229,77,0.45)' },
        DET: { slug: 'det', bg: 'rgba(0,59,120,0.24)', border: 'rgba(237,23,32,0.45)' },
        GSW: { slug: 'gsw', bg: 'rgba(29,66,138,0.20)', border: 'rgba(255,199,44,0.50)' },
        HOU: { slug: 'hou', bg: 'rgba(206,17,38,0.18)', border: 'rgba(206,17,38,0.45)' },
        IND: { slug: 'ind', bg: 'rgba(0,45,98,0.24)', border: 'rgba(253,181,9,0.50)' },
        LAC: { slug: 'lac', bg: 'rgba(190,21,66,0.18)', border: 'rgba(29,66,138,0.45)' },
        LAL: { slug: 'lal', bg: 'rgba(85,37,130,0.22)', border: 'rgba(253,185,39,0.50)' },
        MEM: { slug: 'mem', bg: 'rgba(93,118,153,0.20)', border: 'rgba(18,28,43,0.50)' },
        MIA: { slug: 'mia', bg: 'rgba(152,0,46,0.20)', border: 'rgba(249,160,27,0.45)' },
        MIL: { slug: 'mil', bg: 'rgba(0,71,55,0.26)', border: 'rgba(205,155,90,0.50)' },
        MIN: { slug: 'min', bg: 'rgba(11,55,100,0.24)', border: 'rgba(120,190,90,0.45)' },
        NOP: { slug: 'nop', bg: 'rgba(12,35,64,0.26)', border: 'rgba(197,99,30,0.45)' },
        NYK: { slug: 'nyk', bg: 'rgba(0,107,182,0.20)', border: 'rgba(248,109,35,0.45)' },
        OKC: { slug: 'okc', bg: 'rgba(0,83,155,0.20)', border: 'rgba(239,95,35,0.45)' },
        ORL: { slug: 'orl', bg: 'rgba(0,83,155,0.20)', border: 'rgba(197,166,180,0.45)' },
        PHI: { slug: 'phi', bg: 'rgba(0,53,120,0.24)', border: 'rgba(237,108,26,0.45)' },
        PHX: { slug: 'phx', bg: 'rgba(31,58,88,0.24)', border: 'rgba(229,119,11,0.50)' },
        POR: { slug: 'por', bg: 'rgba(22,53,71,0.26)', border: 'rgba(224,58,62,0.45)' },
        SAC: { slug: 'sac', bg: 'rgba(91,43,130,0.20)', border: 'rgba(99,112,154,0.45)' },
        SAS: { slug: 'sas', bg: 'rgba(0,0,0,0.30)', border: 'rgba(198,146,20,0.50)' },
        TOR: { slug: 'tor', bg: 'rgba(206,17,38,0.18)', border: 'rgba(206,17,38,0.45)' },
        UTA: { slug: 'uta', bg: 'rgba(0,43,92,0.24)', border: 'rgba(0,71,27,0.45)' },
        WAS: { slug: 'was', bg: 'rgba(0,43,92,0.24)', border: 'rgba(229,119,11,0.45)' }
      }
    },

    // ── Storage namespaces ──────────────────────────────────────────────────
    // The ledger key is SHARED across sports (entries are sport-tagged so CLV
    // stats never mix); watchlist/sniper/correlation-dismissal spaces are
    // per-sport. NBA ships NO legacy keys — there is no pre-adapter data.
    storageKeys: {
      ledger: 'propwire_portfolio_ledger_v2',
      watchlist: 'propwire_watchlist_nba',
      sniperConfig: 'propwire_sniper_config_nba',
      dismissedCorrelations: 'propwire_dismissed_correlations_nba'
    },
    legacyKeys: {},

    // ── Circuit breaker fallback ────────────────────────────────────────────
    // PRIMARY SOURCE: viewer/circuit_breaker_config.json sports.nba. These
    // fallbacks are uncalibrated tuning parameters for fetch-failure
    // resilience only. The UI must show the research-only badge whenever
    // calibrated is false.
    breakerFallback: {
      drift_pct_hurdle: 0.15,
      high_edge_caution_hurdle: 0.20,
      cooldown_minutes: 15,
      deadman_switch_max_age_seconds: 300,
      calibrated: false
    },

    /**
     * Correlation rule: same-team, same-market exposure shares minutes and
     * game script (blowout risk, foul trouble, lineup churn). Key shape must
     * stay `${team}::${market}` — dismissal lookups depend on it.
     */
    correlationKey: (row, market) => `${row.team}::${market}`
  };

  NBA_ADAPTER.etDateKey = etDateKey;
  window.PropWireSports.register(NBA_ADAPTER);
})();
